'use strict';

const { bench, group, run, summary } = require('mitata');
const clsx = require('../dist/clsx.js');
const lite = require('../dist/lite.js');

// mitata wraps its default export differently for CJS; normalise to a callable.
const full = typeof clsx === 'function' ? clsx : clsx.clsx || clsx.default;
const slim = typeof lite === 'function' ? lite : lite.clsx || lite.default;

// ---------------------------------------------------------------------------
// Strings
// ---------------------------------------------------------------------------
group('Strings', () => {
	summary(() => {
		bench('clsx', () => full('foo', '', 'bar', 'baz', 'bax', 'bux'));
		bench('clsx/lite', () => slim('foo', '', 'bar', 'baz', 'bax', 'bux'));
	});
});

// ---------------------------------------------------------------------------
// Objects
// ---------------------------------------------------------------------------
group('Objects', () => {
	summary(() => {
		bench('clsx', () => full({ foo: true, bar: true, bax: true, bux: false }, { baz: true, bax: false, bux: true }));
		bench('clsx/lite', () => slim({ foo: true, bar: true, bax: true, bux: false }, { baz: true, bax: false, bux: true }));
	});
});

// ---------------------------------------------------------------------------
// Arrays
// ---------------------------------------------------------------------------
group('Arrays', () => {
	summary(() => {
		bench('clsx', () => full(['foo', 'bar'], ['baz', 'bax', 'bux']));
		bench('clsx/lite', () => slim(['foo', 'bar'], ['baz', 'bax', 'bux']));
	});
});

// ---------------------------------------------------------------------------
// Mixed
// ---------------------------------------------------------------------------
group('Mixed', () => {
	summary(() => {
		bench('clsx', () => full('foo', 'bar', { bax: true, bux: false }, ['baz', { bax: false, bux: true }]));
		bench('clsx/lite', () => slim('foo', 'bar', { bax: true, bux: false }, ['baz', { bax: false, bux: true }]));
	});
});

// ---------------------------------------------------------------------------
// Mixed (Bad Data) — clsx/lite skips non-string values, result differs
// ---------------------------------------------------------------------------
group('Mixed (Bad Data)', () => {
	summary(() => {
		bench('clsx', () => full('foo', 'bar', undefined, null, NaN, () => {}, { bax: true, bux: false, 123: true }, ['baz', { bax: false, bux: true, abc: null }, {}]));
		bench('clsx/lite', () => slim('foo', 'bar', undefined, null, NaN, () => {}, { bax: true, bux: false, 123: true }, ['baz', { bax: false, bux: true, abc: null }, {}]));
	});
});

run();

